import { logoGeometry as g } from "./paths";

/**
 * Concept-stage logo components (not approved final logos). Geometry is generated by
 * scripts/make-logos.py so the standalone SVGs in /public/brand and these inline versions
 * can never drift. Colours come from CSS variables, so each brand world re-tints them.
 */
type P = { className?: string; title?: string };
const role = { ink: "var(--bone)", a: "var(--ember)", b: "var(--coral)", c: "var(--lime)" } as const;
const a11y = (title?: string) => (title ? { role: "img" as const, "aria-label": title } : { "aria-hidden": true as const, focusable: false as const });

function Parts({ parts, sw }: { parts: readonly (readonly [string, string, string])[]; sw?: number }) {
  return (
    <>
      {parts.map(([r, d, kind], i) =>
        kind === "stroke" ? (
          <path
            key={i}
            data-i={i}
            d={d}
            fill="none"
            stroke={role[r as keyof typeof role]}
            strokeWidth={sw}
            strokeLinejoin="miter"
            strokeMiterlimit={8}
          />
        ) : (
          <path key={i} d={d} fill={role[r as keyof typeof role]} />
        ),
      )}
    </>
  );
}

export function TristarMark({ className, title }: P) {
  return (
    <svg viewBox="0 0 100 100" className={className} {...a11y(title)}>
      <Parts parts={g.tristarMark.parts} />
    </svg>
  );
}

/**
 * The A's crossbar is three bars — one per food world. `neon` stacks a static, blurred glow copy under a
 * crisp copy whose strokes "ignite" — the filter is never applied to animated nodes (cheap to paint).
 */
export function TristarWordmark({ className, title, neon }: P & { neon?: boolean }) {
  const [w] = g.tristarWordmark.viewBox;
  const vb = `-4 -14 ${w + 8} 122`;
  const core = (
    <svg viewBox={vb} className={neon ? "neon-core" : className} {...a11y(title)}>
      <Parts parts={g.tristarWordmark.parts} sw={g.tristarWordmark.stroke} />
    </svg>
  );
  if (!neon) return core;
  return (
    <span className={`neon-sign ${className ?? ""}`}>
      <svg viewBox={vb} className="neon-glow" aria-hidden="true" focusable="false">
        <Parts parts={g.tristarWordmark.parts} sw={g.tristarWordmark.stroke} />
      </svg>
      {core}
    </span>
  );
}

export function TristarLockup({ className, title }: P) {
  const [w] = g.tristarWordmark.viewBox;
  return (
    <svg viewBox={`-4 -14 ${w + 150} 122`} className={className} {...a11y(title)}>
      <Parts parts={g.tristarMark.parts} />
      <g transform="translate(130 0)">
        <Parts parts={g.tristarWordmark.parts} sw={g.tristarWordmark.stroke} />
      </g>
    </svg>
  );
}

export function BiryaniLogo({ className, title }: P) {
  const { word, emblem } = g.biryaniLogo;
  const [ww, wh] = word.viewBox;
  const [body, rim, lid, knob] = emblem.parts;
  return (
    <svg viewBox={`0 0 ${Math.max(ww, 200)} ${wh + 262}`} className={className} {...a11y(title)}>
      <g transform={`translate(${(Math.max(ww, 200) - 128 * 1.6) / 2 + 24} 40) scale(1.6)`}>
        {emblem.steam.map((d, i) => (
          <path key={i} className="steam-stroke" d={d} fill="none" stroke="var(--ember)" strokeWidth={5.5} strokeLinecap="round" />
        ))}
        <path d={body[1]} fill="var(--copper)" />
        <path d={rim[1]} fill="var(--gold)" />
        <g transform="translate(14 -14) rotate(-16 94 54)">
          <path d={lid[1]} fill="var(--ember)" />
          <path d={knob[1]} fill="var(--gold)" />
        </g>
      </g>
      <g transform={`translate(${(Math.max(ww, 200) - ww) / 2} ${wh + 250})`}>
        <path d={word.d} fill="var(--bone)" />
      </g>
    </svg>
  );
}

export function SamosaLogo({ className, title }: P) {
  const { word } = g.samosaLogo;
  const [ww, wh] = word.viewBox;
  return (
    <svg viewBox={`0 ${-wh - 6} ${ww + 40} ${wh + 40}`} className={className} {...a11y(title)}>
      <g transform="translate(14 0) skewX(-10)">
        <path d={word.d} fill="var(--bone)" />
        <path d={word.triangle} fill="var(--coral)" />
        <path d={word.crack} fill="none" stroke="var(--ink)" strokeWidth={3.5} />
        <rect x={0} y={14} width={ww} height={7} fill="var(--pink)" />
      </g>
    </svg>
  );
}

export function ThaliLogo({ className, title }: P) {
  const { word, emblem } = g.thaliLogo;
  const [ww, wh] = word.viewBox;
  const w = Math.max(ww, 120);
  return (
    <svg viewBox={`0 0 ${w} ${120 + 28 + wh}`} className={className} {...a11y(title)}>
      <g transform={`translate(${(w - 120) / 2} 0)`}>
        <circle cx={60} cy={60} r={57} fill="none" stroke="var(--bronze)" strokeWidth={3} />
        <circle cx={60} cy={60} r={50} fill="var(--forest)" stroke="var(--lime)" strokeWidth={1.5} />
        {emblem.bowls.map(([x, y], i) => (
          <circle key={i} cx={x} cy={y} r={12} fill="none" stroke="var(--lime)" strokeWidth={3} />
        ))}
        <circle cx={60} cy={60} r={13} fill="var(--lime)" />
      </g>
      <g transform={`translate(${(w - ww) / 2} ${120 + 28 + wh})`}>
        <path d={word.d} fill="var(--bone)" />
      </g>
    </svg>
  );
}
